{
  "technical_and_design_decisions": [
    "Each ported module will be implemented as a standalone Spring Boot application in the spring-cloud-stream (s-c-s) repository, using Spring Cloud Stream's @EnableBinding with the appropriate Source or Sink interface.",
    "The existing Spring XD modules are Spring Integration based, so the porting strategy is to reuse and adapt the existing message handler/channel adapter logic rather than rewrite it, replacing XD-specific wiring with Spring Boot auto-configuration and @ConfigurationProperties classes for externalized options.",
    "A shared parent Maven POM and a common project skeleton (build config, checkstyle, test conventions, binder dependencies) will be established once and reused by all ported modules.",
    "Integration tests will use embedded/in-process test doubles where possible (embedded Redis, embedded RabbitMQ or mock broker, in-memory GemFire, local FTP server, MiniDFSCluster for HDFS) to keep the build self-contained.",
    "The HDP/PHD support work (U7) will be done by upgrading the Hadoop/distro dependency versions and validating HDFS sink behavior against the latest HDP and PHD releases.",
    "The migration documentation (U8) will be added as a dedicated section in the reference documentation covering new features and backward-incompatible changes between XD 1.2 and 1.3."
  ],
  "assumptions": [
    "The developer is experienced with Spring XD, Spring Integration, Spring Boot, and Spring Cloud Stream, and has full access to the XD source code and the target s-c-s repository.",
    "The target stack is consistent with the XD 1.2/1.3 generation (Spring Boot 1.3/1.4, Spring Cloud Stream 1.x, Java 8); the Spring Framework 6 / Java 17 note in the specification is treated as background context, not the target for this migration increment.",
    "All required test infrastructure (embedded brokers, test FTP server, MiniDFSCluster, or equivalent) is available or can be set up within the build without external provisioning effort.",
    "Each module port includes unit tests, integration tests, and a README documenting configuration properties.",
    "Since all work is performed by one developer, code review effort is included as self-review within each activity estimate; no coordination overhead is added.",
    "Estimates are pure development effort (workdays), excluding elapsed-time delays such as environment outages, waiting for CI resources, or external approvals.",
    "The scope of U8 is limited to the 1.2-to-1.3 migration strategy section, not a full documentation rewrite."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Development environment and migration scaffolding setup",
      "activity_description": "Set up local development environment, create the shared parent POM and module skeleton in the s-c-s repository (build plugins, dependency management, test conventions), and establish the reusable porting pattern (binding annotations, configuration properties approach, binder wiring) that all module ports will follow.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A2",
      "activity_name": "Port router sink module (U1)",
      "activity_description": "Analyze the XD router module, port its SpEL-expression-based routing logic to a spring-cloud-stream sink application, create @ConfigurationProperties for routing options, adapt Spring Integration router wiring, and provide unit tests, integration tests, and README documentation.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A3",
      "activity_name": "Port file sink module (U2)",
      "activity_description": "Analyze the XD file module, port its file-writing message handler to a spring-cloud-stream sink application, create configuration properties (directory, filename expression, mode, charset), adapt Spring Integration file outbound wiring, and provide unit tests, integration tests, and README documentation.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A4",
      "activity_name": "Port FTP sink module (U3)",
      "activity_description": "Analyze the XD FTP module, port its FTP session management and outbound transfer logic to a spring-cloud-stream sink application, create configuration properties (host, credentials, remote directory, mode), adapt Spring Integration FTP outbound gateway wiring, test against a local FTP server, and provide unit tests, integration tests, and README documentation.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A5",
      "activity_name": "Move redis sink module (U4)",
      "activity_description": "Move the XD redis module to the s-c-s repository as a spring-cloud-stream sink, adapt its Redis connection and write logic to Spring Boot auto-configuration, create configuration properties, verify against an embedded Redis instance, and provide unit tests, integration tests, and README documentation.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A6",
      "activity_name": "Move rabbit source module (U5)",
      "activity_description": "Move the XD rabbit module to the s-c-s repository as a spring-cloud-stream source, adapt the RabbitMQ inbound channel adapter wiring, create configuration properties (queues, exchanges, connection settings), verify against an embedded or local RabbitMQ broker, and provide unit tests, integration tests, and README documentation.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A7",
      "activity_name": "Move gemfire sink module (U6)",
      "activity_description": "Move the XD gemfire module to the s-c-s repository as a spring-cloud-stream sink, adapt its GemFire region write logic and cache client configuration, create configuration properties, test against an in-memory GemFire instance, and provide unit tests, integration tests, and README documentation.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A8",
      "activity_name": "Support latest HDP/PHD distro releases for HDFS (U7)",
      "activity_description": "Research the latest HDP and PHD distribution releases, upgrade Hadoop/distro dependencies and align versions in the build, resolve compatibility issues, and validate HDFS-related pipeline behavior (e.g., HDFS sink) against the updated distributions using a MiniDFSCluster-based test setup.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A9",
      "activity_name": "Migration strategy documentation 1.2 to 1.3 (U8)",
      "activity_description": "Write a reference documentation section describing the migration strategy from XD 1.2 to 1.3 releases, covering new improvements, behavioral changes, and backward-incompatibility specifics with upgrade guidance.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A10",
      "activity_name": "Cross-module integration and pipeline validation",
      "activity_description": "Perform end-to-end validation of streaming pipelines combining the ported modules (e.g., rabbit source feeding file, FTP, redis, gemfire, and router sinks), verify binder integration end-to-end, and fix cross-module defects.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A11",
      "activity_name": "Build, CI, and release packaging",
      "activity_description": "Configure continuous integration for all new modules, finalize versioning and release metadata, ensure generated starters/apps are packaged correctly, and perform the final self-review and clean-up before delivery.",
      "most_likely_effort": 2
    }
  ],
  "reported_total": {
    "most_likely_effort": 35
  }
}

